o.cardinality=await q(`select ${cols.map(c=>`count(distinct "${c}") "${c}"`).join(',')} from read_parquet('${esc}')`);
o.nulls=await q(`select ${cols.map(c=>`count(*) filter(where "${c}" is null) "${c}"`).join(',')} from read_parquet('${esc}')`);
o.values={}; for(const c of cols){const card=o.cardinality[0][c]; if(Number(card)<=50)o.values[c]=await q(`select "${c}" v,count(*) n from read_parquet('${esc}') group by 1 order by 1`)}
o.fullDuplicates=await q(`select coalesce(sum(n-1),0) duplicate_rows,count(*) duplicate_groups from (select count(*) n from read_parquet('${esc}') group by all having count(*)>1)`);
const dims=cols.filter(c=>!['OBS_VALUE','UNIT','UNIT_MULT','DECIMALS','OBS_STATUS','SOURCE_SHEET','CUADRO_TITLE'].includes(c)); o.keyDuplicates=await q(`select coalesce(sum(n-1),0) duplicate_rows,count(*) duplicate_groups,max(n) max_multiplicity from (select count(*) n from read_parquet('${esc}') group by ${dims.map(x=>'"'+x+'"').join(',')} having count(*)>1)`);
o.keyDupSamples=await q(`select ${dims.map(x=>'"'+x+'"').join(',')},count(*) n,count(distinct OBS_VALUE) vals,min(OBS_VALUE) mn,max(OBS_VALUE) mx from read_parquet('${esc}') group by ${dims.map(x=>'"'+x+'"').join(',')} having count(*)>1 order by n desc limit 10`);
o.indicators=await q(`select INDICATOR,count(*) rows,min(TIME_PERIOD) start,max(TIME_PERIOD) finish,count(distinct TIME_PERIOD) periods,count(distinct UNIT) units,count(distinct CATEGORY) categories from read_parquet('${esc}') group by 1 order by 1`);
o.anomalies=await q(`select count(*) filter(where not regexp_full_match(TIME_PERIOD,'[0-9]{4}')) invalid_time, count(*) filter(where FREQ<>'A') nonannual, count(*) filter(where REF_AREA not like 'CO%') bad_ref, count(*) filter(where OBS_VALUE is null) null_obs, count(*) filter(where UNIT_MULT is null) null_mult, count(*) filter(where DECIMALS is null) null_decimals from read_parquet('${esc}')`);
console.log(JSON.stringify(safe(o),null,2)); db.close();})().catch(e=>{console.error(e);process.exit(1)});

